107	func handleInterruptAnalyze(w http.ResponseWriter, r *http.Request) {
108		if r.Method != http.MethodPost {
109			w.Header().Set("Allow", http.MethodPost)
110			writeAnalyzeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
111			return
112		}
113		var req interruptRequest
114		if !decodeStrictJSON(w, r, &req) {
115			return
116		}
117		tasks, intrs, horizon, ok := validateInterruptRequest(&req)
118		if !ok {
119			writeAnalyzeError(w, http.StatusUnprocessableEntity, "validation_failed")
120			return
121		}
122		w.Header().Set("Content-Type", "application/json; charset=utf-8")
123		w.WriteHeader(http.StatusOK)
124		_ = json.NewEncoder(w).Encode(simulateInterrupt(tasks, intrs, horizon))
125	}
126	
127	// validateInterruptRequest enforces the one-shot task constraints (without
128	// execution) plus the action-program and interrupt rules: 1..1024 actions per
129	// task, each exactly one of {"run":N} or {"critical":N} with a positive
130	// duration; 1..4096 interrupts with unique ids, 0..255 priorities, arrivals
131	// inside the horizon, positive executions and deadlines past their arrivals.
132	// The grand total of all action durations and interrupt executions must fit
133	// int64.
134	func validateInterruptRequest(req *interruptRequest) ([]intTask, []intIntr, int64, bool) {
135		if req.Horizon == nil || *req.Horizon <= 0 || *req.Horizon > maxHorizon {
136			return nil, nil, 0, false
137		}
138		horizon := *req.Horizon
139		if req.Tasks == nil || len(*req.Tasks) == 0 || len(*req.Tasks) > maxTasks {
140			return nil, nil, 0, false
141		}
142		if req.Interrupts == nil || len(*req.Interrupts) == 0 || len(*req.Interrupts) > maxInterrupts {
143			return nil, nil, 0, false
144		}
145		var total int64
146		tasks := make([]intTask, 0, len(*req.Tasks))
147		ids := make(map[string]struct{}, len(*req.Tasks))
148		for i := range *req.Tasks {
149			in := (*req.Tasks)[i]
150			if !validTaskID(in.ID) {
151				return nil, nil, 0, false
152			}
153			if _, dup := ids[in.ID]; dup {
154				return nil, nil, 0, false
155			}
156			ids[in.ID] = struct{}{}
157			if in.Priority == nil || *in.Priority < 0 || *in.Priority > 255 {
158				return nil, nil, 0, false
159			}
160			if in.Release == nil || *in.Release < 0 || *in.Release >= horizon {
161				return nil, nil, 0, false
162			}
163			if in.Deadline == nil || *in.Deadline <= *in.Release {
164				return nil, nil, 0, false
165			}
166			if in.Actions == nil || len(*in.Actions) == 0 || len(*in.Actions) > maxInterruptActions {
167				return nil, nil, 0, false
168			}
169			actions := make([]intAction, 0, len(*in.Actions))
170			var taskTotal int64
171			for j := range *in.Actions {
172				ai := (*in.Actions)[j]
173				verbs := 0
174				if ai.Run != nil {
175					verbs++
176				}
177				if ai.Critical != nil {
178					verbs++
179				}
180				if verbs != 1 {
181					return nil, nil, 0, false
182				}
183				critical := ai.Critical != nil
184				var duration int64
185				if critical {
186					duration = *ai.Critical
187				} else {
188					duration = *ai.Run
189				}
190				if duration <= 0 {
191					return nil, nil, 0, false
192				}
193				var ok bool
194				taskTotal, ok = saturatingAdd(taskTotal, duration)
195				if !ok {
196					return nil, nil, 0, false
197				}
198				actions = append(actions, intAction{critical: critical, duration: duration})
199			}
200			var ok bool
201			total, ok = saturatingAdd(total, taskTotal)
202			if !ok {
203				return nil, nil, 0, false
204			}
205			tasks = append(tasks, intTask{
206				id:       in.ID,
207				priority: *in.Priority,
208				release:  *in.Release,
209				deadline: *in.Deadline,
210				actions:  actions,
211			})
212		}
213		intrs := make([]intIntr, 0, len(*req.Interrupts))
214		iids := make(map[string]struct{}, len(*req.Interrupts))
215		for i := range *req.Interrupts {
216			in := (*req.Interrupts)[i]
217			if !validTaskID(in.ID) {
218				return nil, nil, 0, false
219			}
220			if _, dup := iids[in.ID]; dup {
221				return nil, nil, 0, false
222			}
223			iids[in.ID] = struct{}{}
224			if in.Priority == nil || *in.Priority < 0 || *in.Priority > 255 {
225				return nil, nil, 0, false
226			}
227			if in.Arrival == nil || *in.Arrival < 0 || *in.Arrival >= horizon {
228				return nil, nil, 0, false
229			}
230			if in.Execution == nil || *in.Execution <= 0 {
231				return nil, nil, 0, false
232			}
233			if in.Deadline == nil || *in.Deadline <= *in.Arrival {
234				return nil, nil, 0, false
235			}
236			var ok bool
237			total, ok = saturatingAdd(total, *in.Execution)
238			if !ok {
239				return nil, nil, 0, false
240			}
241			intrs = append(intrs, intIntr{
242				id:        in.ID,
243				priority:  *in.Priority,
244				arrival:   *in.Arrival,
245				execution: *in.Execution,
246				deadline:  *in.Deadline,
247			})
248		}
249		return tasks, intrs, horizon, true
250	}
251	
252	// intSegment is an unmerged execution interval recorded by the simulation.
253	type intSegment struct {
254		interrupt  bool
255		index      int
256		critical   bool
257		start, end int64
258	}
259	
260	// critSection tracks one critical action of a task. A started critical
261	// section is non-preemptible, so it executes as a single contiguous interval:
262	// end stays nil only when the horizon truncates it.
263	type critSection struct {
264		actionIndex int
265		start       *int64
266		end         *int64
267		observed    int64
268		completed   bool
269	}
270	
271	// simulateInterrupt runs an event-driven single-core simulation over
272	// [0, horizon) where interrupts always outrank tasks. A task's critical
273	// action, once started, cannot be preempted by anything; its run actions are
274	// preemptible by higher-priority tasks and by any interrupt. Interrupts are
275	// preempted only by strictly-higher-priority interrupts and resume afterwards.
276	// At any instant all arrivals and releases are incorporated before selection;
277	// ties break by arrival/release, then input order.
278	func simulateInterrupt(tasks []intTask, intrs []intIntr, horizon int64) interruptResponse {
279		n, m := len(tasks), len(intrs)
280	
281		pc := make([]int, n)
282		runRem := make([]int64, n)
283		released := make([]bool, n)
284		completedT := make([]bool, n)
285		executedT := make([]int64, n)
286		completionT := make([]*int64, n)
287	
288		crits := make([][]critSection, n)
289		critSlot := make([][]int, n)
290		for i, t := range tasks {
291			critSlot[i] = make([]int, len(t.actions))
292			for j, a := range t.actions {
293				if a.critical {
294					critSlot[i][j] = len(crits[i])
295					crits[i] = append(crits[i], critSection{actionIndex: j})
296				} else {
297					critSlot[i][j] = -1
298				}
299			}
300		}
301	
302		remI := make([]int64, m)
303		executedI := make([]int64, m)
304		arrived := make([]bool, m)
305		startI := make([]*int64, m)
306		completionI := make([]*int64, m)
307		for i, in := range intrs {
308			remI[i] = in.execution
309		}
310	
311		// Indices sorted by (release or arrival, input order) for event
312		// bookkeeping and same-priority tie breaking.
313		taskOrder := make([]int, n)
314		for i := range taskOrder {
315			taskOrder[i] = i
316		}
317		sort.Slice(taskOrder, func(a, b int) bool {
318			ia, ib := taskOrder[a], taskOrder[b]
319			if tasks[ia].release != tasks[ib].release {
320				return tasks[ia].release < tasks[ib].release
321			}
322			return ia < ib
323		})
324		intrOrder := make([]int, m)
325		for i := range intrOrder {
326			intrOrder[i] = i
327		}
328		sort.Slice(intrOrder, func(a, b int) bool {
329			ia, ib := intrOrder[a], intrOrder[b]
330			if intrs[ia].arrival != intrs[ib].arrival {
331				return intrs[ia].arrival < intrs[ib].arrival
332			}
333			return ia < ib
334		})
335		nextRel, nextArr := 0, 0
336	
337		const (
338			kindNone = iota - 1
339			kindTask
340			kindIntr
341		)
342		var segs []intSegment
343		curKind, curIdx := kindNone, 0
344		var now int64
345		doneT, doneI := 0, 0
346	
347		for now < horizon {
348			for nextRel < n && tasks[taskOrder[nextRel]].release <= now {
349				released[taskOrder[nextRel]] = true
350				nextRel++
351			}
352			for nextArr < m && intrs[intrOrder[nextArr]].arrival <= now {
353				arrived[intrOrder[nextArr]] = true
354				nextArr++
355			}
356			if curKind == kindTask && completedT[curIdx] {
357				curKind = kindNone
358			}
359			if curKind == kindIntr && remI[curIdx] == 0 {
360				curKind = kindNone
361			}
362	
363			// Best ready interrupt: smallest priority, then earliest arrival,
364			// then earliest input index. Any ready interrupt outranks any task.
365			bi := -1
366			for i := 0; i < m; i++ {
367				if !arrived[i] || remI[i] <= 0 {
368					continue
369				}
370				if bi == -1 ||
371					intrs[i].priority < intrs[bi].priority ||
372					(intrs[i].priority == intrs[bi].priority && intrs[i].arrival < intrs[bi].arrival) ||
373					(intrs[i].priority == intrs[bi].priority && intrs[i].arrival == intrs[bi].arrival && i < bi) {
374					bi = i
375				}
376			}
377			if bi != -1 {
378				// A strictly higher priority interrupt preempts; equal never does.
379				if curKind != kindIntr || (bi != curIdx && intrs[bi].priority < intrs[curIdx].priority) {
380					curKind, curIdx = kindIntr, bi
381				}
382			} else {
383				if curKind == kindIntr {
384					curKind = kindNone
385				}
386				// Best runnable task: smallest priority, then earliest release,
387				// then earliest input index.
388				bt := -1
389				for i := 0; i < n; i++ {
390					if !released[i] || completedT[i] {
391						continue
392					}
393					if bt == -1 ||
394						tasks[i].priority < tasks[bt].priority ||
395						(tasks[i].priority == tasks[bt].priority && tasks[i].release < tasks[bt].release) ||
396						(tasks[i].priority == tasks[bt].priority && tasks[i].release == tasks[bt].release && i < bt) {
397						bt = i
398					}
399				}
400				if curKind == kindNone {
401					if bt != -1 {
402						curKind, curIdx = kindTask, bt
403					}
404				} else if bt != -1 && bt != curIdx && tasks[bt].priority < tasks[curIdx].priority {
405					curIdx = bt
406				}
407			}
408	
409			if curKind == kindNone {
410				// Idle: jump to the next release or arrival (or stop when every
411				// task and interrupt is done; now is the completion time).
412				next := int64(-1)
413				if nextRel < n {
414					next = tasks[taskOrder[nextRel]].release
415				}
416				if nextArr < m {
417					if a := intrs[intrOrder[nextArr]].arrival; next == -1 || a < next {
418						next = a
419					}
420				}
421				if next == -1 {
422					break
423				}
424				now = next
425				continue
426			}
427	
428			// Run until the action or interrupt completes, the horizon cuts it,
429			// or a preempting event occurs. A critical section ignores events.
430			critical := false
431			runEnd := horizon
432			if curKind == kindTask {
433				act := tasks[curIdx].actions[pc[curIdx]]
434				if runRem[curIdx] == 0 {
435					runRem[curIdx] = act.duration
436				}
437				critical = act.critical
438				if rem := runRem[curIdx]; rem < horizon-now {
439					runEnd = now + rem
440				}
441				if !critical {
442					// Any interrupt arrival preempts a running task.
443					if nextArr < m {
444						if a := intrs[intrOrder[nextArr]].arrival; a < runEnd {
445							runEnd = a
446						}
447					}
448					// The earliest strictly-higher-priority release preempts.
449					for k := nextRel; k < n; k++ {
450						j := taskOrder[k]
451						if tasks[j].release >= runEnd {
452							break
453						}
454						if tasks[j].priority < tasks[curIdx].priority {
455							runEnd = tasks[j].release
456							break
457						}
458					}
459				}
460			} else {
461				if rem := remI[curIdx]; rem < horizon-now {
462					runEnd = now + rem
463				}
464				// The earliest strictly-higher-priority arrival preempts.
465				for k := nextArr; k < m; k++ {
466					j := intrOrder[k]
467					if intrs[j].arrival >= runEnd {
468						break
469					}
470					if intrs[j].priority < intrs[curIdx].priority {
471						runEnd = intrs[j].arrival
472						break
473					}
474				}
475			}
476	
477			segs = append(segs, intSegment{
478				interrupt: curKind == kindIntr,
479				index:     curIdx,
480				critical:  critical,
481				start:     now,
482				end:       runEnd,
483			})
484			delta := runEnd - now
485			if curKind == kindTask {
486				executedT[curIdx] += delta
487				runRem[curIdx] -= delta
488				var rec *critSection
489				if critical {
490					rec = &crits[curIdx][critSlot[curIdx][pc[curIdx]]]
491					s := now
492					rec.start = &s
493				}
494				now = runEnd
495				if runRem[curIdx] == 0 {
496					if critical {
497						e := now
498						rec.end = &e
499						rec.observed = e - *rec.start
500						rec.completed = true
501					}
502					pc[curIdx]++
503					if pc[curIdx] == len(tasks[curIdx].actions) {
504						completedT[curIdx] = true
505						c := now
506						completionT[curIdx] = &c
507						doneT++
508					}
509				} else if critical {
510					// Truncated by the horizon: end stays null.
511					rec.observed = now - *rec.start
512				}
513			} else {
514				executedI[curIdx] += delta
515				remI[curIdx] -= delta
516				if startI[curIdx] == nil {
517					s := now
518					startI[curIdx] = &s
519				}
520				now = runEnd
521				if remI[curIdx] == 0 {
522					c := now
523					completionI[curIdx] = &c
524					doneI++
525				}
526			}
527		}
528	
529		// Merge adjacent intervals of the same actor and mode; idle is omitted.
530		timeline := make([]interruptTimelineInterval, 0, len(segs))
531		for _, seg := range segs {
532			actorType, actorID, mode := "task", "", "run"
533			if seg.interrupt {
534				actorType, actorID = "interrupt", intrs[seg.index].id
535			} else {
536				actorID = tasks[seg.index].id
537			}
538			if seg.critical {
539				mode = "critical"
540			}
541			last := len(timeline) - 1
542			if last >= 0 && timeline[last].ActorType == actorType &&
543				timeline[last].ActorID == actorID && timeline[last].Mode == mode &&
544				timeline[last].End == seg.start {
545				timeline[last].End = seg.end
546				continue
547			}
548			timeline = append(timeline, interruptTimelineInterval{
549				ActorType: actorType,
550				ActorID:   actorID,
551				Mode:      mode,
552				Start:     seg.start,
553				End:       seg.end,
554			})
555		}
556	
557		deadlineStatus := func(completion *int64, deadline int64) string {
558			switch {
559			case completion != nil && *completion <= deadline:
560				return "met"
561			case completion != nil:
562				return "missed"
563			case deadline <= horizon:
564				return "missed"
565			default:
566				return "pending"
567			}
568		}
569	
570		taskResults := make([]interruptTaskResult, n)
571		for i, t := range tasks {
572			taskResults[i] = interruptTaskResult{
573				ID:             t.id,
574				Executed:       executedT[i],
575				Completion:     completionT[i],
576				DeadlineStatus: deadlineStatus(completionT[i], t.deadline),
577			}
578		}
579		interruptResults := make([]interruptResult, m)
580		for i, in := range intrs {
581			var latency *int64
582			if startI[i] != nil {
583				l := *startI[i] - in.arrival
584				latency = &l
585			}
586			interruptResults[i] = interruptResult{
587				ID:             in.id,
588				Executed:       executedI[i],
589				Completion:     completionI[i],
590				DeadlineStatus: deadlineStatus(completionI[i], in.deadline),
591				Start:          startI[i],
592				Latency:        latency,
593			}
594		}
595		var sections []criticalSectionResult
596		for i, t := range tasks {
597			for _, rec := range crits[i] {
598				sections = append(sections, criticalSectionResult{
599					TaskID:           t.id,
600					ActionIndex:      rec.actionIndex,
601					Start:            rec.start,
602					End:              rec.end,
603					ObservedDuration: rec.observed,
604					Completed:        rec.completed,
605				})
606			}
607		}
608		if sections == nil {
609			sections = []criticalSectionResult{}
610		}
611	
612		status := "horizon"
613		stoppedAt := horizon
614		if doneT == n && doneI == m {
615			status = "completed"
616			stoppedAt = now
617		}
618		return interruptResponse{
619			Status:           status,
620			StoppedAt:        stoppedAt,
621			Timeline:         timeline,
622			TaskResults:      taskResults,
623			InterruptResults: interruptResults,
624			CriticalSections: sections,
625		}
626	}
