1	package server
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"mime"
10		"net/http"
11		"sort"
12		"unicode"
13		"unicode/utf8"
14	)
15	
16	const (
17		analyzePath  = "/v1/schedules/analyze"
18		maxBodyBytes = 1 << 20
19		maxHorizon   = 1_000_000_000_000
20		maxTasks     = 256
21		maxIDRunes   = 64
22	)
23	
24	type analyzeTaskIn struct {
25		ID        string `json:"id"`
26		Priority  *int64 `json:"priority"`
27		Release   *int64 `json:"release"`
28		Execution *int64 `json:"execution"`
29		Deadline  *int64 `json:"deadline"`
30	}
31	
32	type analyzeRequest struct {
33		Horizon *int64           `json:"horizon"`
34		Tasks   *[]analyzeTaskIn `json:"tasks"`
35	}
36	
37	type timelineInterval struct {
38		TaskID string `json:"taskId"`
39		Start  int64  `json:"start"`
40		End    int64  `json:"end"`
41	}
42	
43	type taskResult struct {
44		Executed       int64  `json:"executed"`
45		Remaining      int64  `json:"remaining"`
46		Completion     *int64 `json:"completion"`
47		DeadlineStatus string `json:"deadlineStatus"`
48	}
49	
50	type analyzeResponse struct {
51		Timeline []timelineInterval `json:"timeline"`
52		Results  []taskResult       `json:"results"`
53	}
54	
55	type scheduledTask struct {
56		id        string
57		priority  int64
58		release   int64
59		execution int64
60		deadline  int64
61	}
62	
63	func handleAnalyze(w http.ResponseWriter, r *http.Request) {
64		if r.Method != http.MethodPost {
65			w.Header().Set("Allow", http.MethodPost)
66			writeAnalyzeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
67			return
68		}
69		var req analyzeRequest
70		if !decodeStrictJSON(w, r, &req) {
71			return
72		}
73		tasks, ok := validateAnalyzeRequest(&req)
74		if !ok {
75			writeAnalyzeError(w, http.StatusUnprocessableEntity, "validation_failed")
76			return
77		}
78		resp := simulateSchedule(tasks, *req.Horizon)
79		w.Header().Set("Content-Type", "application/json; charset=utf-8")
80		w.WriteHeader(http.StatusOK)
81		_ = json.NewEncoder(w).Encode(resp)
82	}
83	
84	func writeAnalyzeError(w http.ResponseWriter, status int, code string) {
85		http.Error(w, `{"error":{"code":"`+code+`"}}`, status)
86	}
87	
88	// decodeStrictJSON implements the request-reading rules shared by every JSON
89	// analysis endpoint. It writes the error response itself and reports whether
90	// the request may proceed; the caller therefore has no partial result to leak.
91	//
92	// Ordering: non-application/json (including a missing media type) is 415; a
93	// body larger than 1 MiB or any syntactic defect (bad syntax, trailing
94	// content, duplicate or unknown keys) is 400 invalid_json; well-formed JSON
95	// whose values do not match the target schema is 422 validation_failed.
96	func decodeStrictJSON(w http.ResponseWriter, r *http.Request, dst any) bool {
97		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
98		if err != nil || mediaType != "application/json" {
99			writeAnalyzeError(w, http.StatusUnsupportedMediaType, "unsupported_media_type")
100			return false
101		}
102		body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
103		if err != nil {
104			writeAnalyzeError(w, http.StatusBadRequest, "invalid_json")
105			return false
106		}
107		// Reject duplicate keys and trailing tokens before the strict struct decode.
108		if err := rejectDuplicateKeys(body); err != nil {
109			writeAnalyzeError(w, http.StatusBadRequest, "invalid_json")
110			return false
111		}
112		dec := json.NewDecoder(bytes.NewReader(body))
113		dec.DisallowUnknownFields()
114		if err := dec.Decode(dst); err != nil {
