83		Status         string                `json:"status"`
84		StoppedAt      int64                 `json:"stoppedAt"`
85		Timeline       []semTimelineInterval `json:"timeline"`
86		Results        []semTaskResult       `json:"results"`
87		FaultAt        *int64                `json:"faultAt,omitempty"`
88		FaultTask      *string               `json:"faultTask,omitempty"`
89		FaultSemaphore *string               `json:"faultSemaphore,omitempty"`
90	}
91	
92	func handleSemaphoreAnalyze(w http.ResponseWriter, r *http.Request) {
93		if r.Method != http.MethodPost {
94			w.Header().Set("Allow", http.MethodPost)
95			writeAnalyzeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
96			return
97		}
98		var req semRequest
99		if !decodeStrictJSON(w, r, &req) {
100			return
101		}
102		tasks, decls, ok := validateSemaphoreRequest(&req)
103		if !ok {
104			writeAnalyzeError(w, http.StatusUnprocessableEntity, "validation_failed")
105			return
106		}
107		w.Header().Set("Content-Type", "application/json; charset=utf-8")
108		w.WriteHeader(http.StatusOK)
109		_ = json.NewEncoder(w).Encode(simulateSemaphore(tasks, decls, *req.Horizon))
110	}
111	
112	// validateSemaphoreRequest enforces the one-shot task constraints (without
113	// execution), the semaphore declarations (1..256 unique id-shaped names with
114	// maximum 1..65535 and initial 0..maximum) and the action-program rules:
115	// exactly one verb per action, positive run microseconds, wait/post references
116	// pointing at declared semaphores, and per-task and global run totals that fit
117	// int64.
118	func validateSemaphoreRequest(req *semRequest) ([]semTask, map[string]semDecl, bool) {
119		if req.Horizon == nil || *req.Horizon <= 0 || *req.Horizon > maxHorizon {
120			return nil, nil, false
121		}
122		if req.Semaphores == nil || len(*req.Semaphores) == 0 || len(*req.Semaphores) > maxSemaphores {
123			return nil, nil, false
124		}
125		decls := make(map[string]semDecl, len(*req.Semaphores))
126		for i := range *req.Semaphores {
127			sd := (*req.Semaphores)[i]
128			if !validTaskID(sd.Name) {
129				return nil, nil, false
130			}
131			if _, dup := decls[sd.Name]; dup {
132				return nil, nil, false
133			}
134			if sd.Maximum == nil || *sd.Maximum < 1 || *sd.Maximum > maxSemaphoreMaximum {
135				return nil, nil, false
136			}
137			if sd.Initial == nil || *sd.Initial < 0 || *sd.Initial > *sd.Maximum {
138				return nil, nil, false
139			}
140			decls[sd.Name] = semDecl{initial: *sd.Initial, maximum: *sd.Maximum}
141		}
142		if req.Tasks == nil || len(*req.Tasks) == 0 || len(*req.Tasks) > maxTasks {
143			return nil, nil, false
144		}
145		horizon := *req.Horizon
146		tasks := make([]semTask, 0, len(*req.Tasks))
147		ids := make(map[string]struct{}, len(*req.Tasks))
148		var totalRun int64
149		for i := range *req.Tasks {
150			in := (*req.Tasks)[i]
151			if !validTaskID(in.ID) {
152				return nil, nil, false
153			}
154			if _, dup := ids[in.ID]; dup {
155				return nil, nil, false
156			}
157			ids[in.ID] = struct{}{}
158			if in.Priority == nil || *in.Priority < 0 || *in.Priority > 255 {
159				return nil, nil, false
160			}
161			if in.Release == nil || *in.Release < 0 || *in.Release >= horizon {
162				return nil, nil, false
163			}
164			if in.Deadline == nil || *in.Deadline <= *in.Release {
165				return nil, nil, false
166			}
167			if in.Actions == nil || len(*in.Actions) == 0 || len(*in.Actions) > maxSemaphoreActions {
168				return nil, nil, false
169			}
170	
171			actions := make([]semAction, 0, len(*in.Actions))
172			var taskRun int64
173			for j := range *in.Actions {
174				ai := (*in.Actions)[j]
175				verbs := 0
176				if ai.Run != nil {
177					verbs++
178				}
179				if ai.Wait != nil {
180					verbs++
181				}
182				if ai.Post != nil {
183					verbs++
184				}
185				if verbs != 1 {
186					return nil, nil, false
187				}
188				switch {
189				case ai.Run != nil:
190					if *ai.Run <= 0 {
191						return nil, nil, false
192					}
193					var ok bool
194					taskRun, ok = saturatingAdd(taskRun, *ai.Run)
195					if !ok {
196						return nil, nil, false
197					}
198					actions = append(actions, semAction{kind: semActRun, run: *ai.Run})
199				case ai.Wait != nil:
200					name := *ai.Wait
201					if _, ok := decls[name]; !ok {
202						return nil, nil, false
203					}
204					actions = append(actions, semAction{kind: semActWait, name: name})
205				default:
206					name := *ai.Post
207					if _, ok := decls[name]; !ok {
208						return nil, nil, false
209					}
210					actions = append(actions, semAction{kind: semActPost, name: name})
211				}
212			}
213			var ok bool
214			totalRun, ok = saturatingAdd(totalRun, taskRun)
215			if !ok {
216				return nil, nil, false
217			}
218			tasks = append(tasks, semTask{
219				id:       in.ID,
220				priority: *in.Priority,
221				release:  *in.Release,
222				deadline: *in.Deadline,
223				actions:  actions,
224			})
225		}
226		return tasks, decls, true
227	}
228	
229	// semSegment is an unmerged run interval recorded by the simulation.
230	type semSegment struct {
231		index      int
232		start, end int64
233	}
234	
235	// semSim is an event-driven single-core simulation of counting semaphores.
236	// Time advances only through run actions; wait, post and completion happen at
237	// a single instant. A post always prefers direct delivery to the earliest
238	// blocked waiter (the count is unchanged); with no waiters it increments the
239	// count, and a count already at maximum is an overflow fault that stops the
240	// analysis on the spot.
241	type semSim struct {
242		tasks   []semTask
243		n       int
244		horizon int64
245		maximum map[string]int64
246	
247		count   map[string]int64
248		waiters map[string][]int // semaphore -> tasks blocked on wait
249	
250		blockedS  []string // semaphore name when blocked, "" otherwise
251		blockTime []int64
252		pc        []int   // next action to interpret
253		runRem    []int64 // remainder of the run action at pc
254	
255		released   []bool
256		completed  []bool
257		executed   []int64
258		completion []*int64
259	
260		order   []int // tasks sorted by (release, input index)
261		nextRel int
262		segs    []semSegment
263		current int
264		now     int64
265	
266		faultTask int
267		faultSem  string
268	}
269	
270	func simulateSemaphore(tasks []semTask, decls map[string]semDecl, horizon int64) semResponse {
271		n := len(tasks)
272		s := &semSim{
273			tasks:      tasks,
274			n:          n,
275			horizon:    horizon,
276			maximum:    make(map[string]int64, len(decls)),
277			count:      make(map[string]int64, len(decls)),
278			waiters:    make(map[string][]int),
279			blockedS:   make([]string, n),
280			blockTime:  make([]int64, n),
281			pc:         make([]int, n),
282			runRem:     make([]int64, n),
283			released:   make([]bool, n),
284			completed:  make([]bool, n),
285			executed:   make([]int64, n),
286			completion: make([]*int64, n),
287			current:    -1,
288		}
289		for name, d := range decls {
290			s.maximum[name] = d.maximum
291			s.count[name] = d.initial
292		}
293		s.order = make([]int, n)
294		for i := range s.order {
295			s.order[i] = i
296		}
297		sort.Slice(s.order, func(a, b int) bool {
298			ia, ib := s.order[a], s.order[b]
299			if tasks[ia].release != tasks[ib].release {
300				return tasks[ia].release < tasks[ib].release
301			}
302			return ia < ib
303		})
304	
305		overflow := false
306		stalled := false
307	loop:
308		for {
309			s.releaseUpTo()
310	
311			// After any state change, first drain the current task's consecutive
312			// zero-duration actions, then schedule.
313			if s.current != -1 {
314				if s.settle(s.current) {
315					overflow = true
316					break
317				}
318				if !s.runnable(s.current) {
319					s.current = -1
320				}
321			}
322	
323			if s.current == -1 {
324				best := s.pickBest()
325				if best == -1 {
326					// Nothing runnable: with no pending release every unfinished
327					// task is blocked, so the simulation stalls here; otherwise
328					// jump to the next release.
329					if s.nextRel >= n {
330						stalled = !s.allCompleted()
331						break loop
332					}
333					s.now = tasks[s.order[s.nextRel]].release
334					continue
335				}
336				s.current = best
337				if s.settle(best) {
338					overflow = true
339					break
340				}
341				if !s.runnable(best) {
342					s.current = -1
343					continue
344				}
345			}
346	
347			// A freshly selected task's zero-duration chain can unblock a strictly
348			// higher-priority task at the same instant. Re-resolve until the
349			// selection is stable; equal priority never preempts.
350			for {
351				best := s.pickBest()
352				if best != -1 && best != s.current && tasks[best].priority < tasks[s.current].priority {
353					s.current = best
354					if s.settle(best) {
355						overflow = true
356						break loop
357					}
358					if !s.runnable(best) {
359						s.current = -1
360						continue loop
361					}
362					continue
363				}
364				break
365			}
366	
367			if s.now >= horizon {
368				break
369			}
370			cur := s.current
371			// Advance until the run completes, the horizon cuts it, or a strictly
372			// higher-priority task releases.
373			rem := s.runRem[cur]
374			length := rem
375			if avail := horizon - s.now; length > avail {
376				length = avail
377			}
378			end := s.now + length
379			for k := s.nextRel; k < n; k++ {
380				j := s.order[k]
381				if tasks[j].priority < tasks[cur].priority &&
382					tasks[j].release > s.now && tasks[j].release < end {
383					end = tasks[j].release
384				}
385			}
386			s.segs = append(s.segs, semSegment{index: cur, start: s.now, end: end})
387			delta := end - s.now
388			s.executed[cur] += delta
389			s.now = end
390			if rem -= delta; rem > 0 {
391				s.runRem[cur] = rem
392				continue
393			}
394			s.runRem[cur] = 0
395			s.pc[cur]++
396			if s.now >= horizon {
397				// The run ends exactly at the horizon: matching the one-shot
398				// baseline, releases strictly before the horizon are already in
399				// effect, so account for them before draining this task's trailing
400				// zero-duration actions once. Nothing else gets to run.
401				s.releaseUpTo()
402				if s.settle(cur) {
403					overflow = true
404				}
405				break
406			}
407		}
408	
409		return s.buildResponse(overflow, stalled)
410	}
411	
412	// settle drains the task's consecutive zero-duration actions. It stops when
413	// the task faces a run action (arming its remainder), blocks, or completes.
414	// It reports whether a post hit a full semaphore with no waiters (overflow).
415	func (s *semSim) settle(i int) bool {
416		for {
417			t := s.tasks[i]
418			if s.pc[i] >= len(t.actions) {
419				s.completed[i] = true
420				now := s.now
421				s.completion[i] = &now
422				return false
423			}
424			a := t.actions[s.pc[i]]
425			switch a.kind {
426			case semActRun:
427				if s.runRem[i] == 0 {
428					s.runRem[i] = a.run
429				}
430				return false
431			case semActWait:
432				m := a.name
433				if s.count[m] > 0 {
434					s.count[m]--
435					s.pc[i]++
436					continue
437				}
438				// Empty semaphore: the task blocks on it.
439				s.blockedS[i] = m
440				s.blockTime[i] = s.now
441				s.waiters[m] = append(s.waiters[m], i)
442				return false
443			case semActPost:
444				m := a.name
445				// Direct delivery to the earliest blocked waiter wins over
446				// incrementing; the count is unchanged.
447				if ws := s.waiters[m]; len(ws) > 0 {
448					w := earliestBlocked(ws, s.blockTime)
449					s.waiters[m] = removeBlocked(ws, w)
450					s.blockedS[w] = ""
451					s.pc[w]++
452					s.pc[i]++
453					continue
454				}
455				if s.count[m] >= s.maximum[m] {
456					s.faultTask = i
457					s.faultSem = m
458					return true
459				}
460				s.count[m]++
461				s.pc[i]++
462			}
463		}
464	}
465	
466	// pickBest selects the runnable task with the highest priority, breaking ties
467	// by release time then input index.
468	func (s *semSim) pickBest() int {
469		best := -1
470		for i := 0; i < s.n; i++ {
471			if !s.released[i] || s.completed[i] || s.blockedS[i] != "" {
472				continue
473			}
474			if best == -1 {
475				best = i
476				continue
477			}
478			a, b := s.tasks[i], s.tasks[best]
479			if a.priority < b.priority ||
480				(a.priority == b.priority && a.release < b.release) ||
481				(a.priority == b.priority && a.release == b.release && i < best) {
482				best = i
483			}
484		}
485		return best
486	}
487	
488	func (s *semSim) runnable(i int) bool {
489		return s.released[i] && !s.completed[i] && s.blockedS[i] == "" && s.runRem[i] > 0
490	}
491	
492	func (s *semSim) releaseUpTo() {
493		for s.nextRel < s.n && s.tasks[s.order[s.nextRel]].release <= s.now {
494			s.released[s.order[s.nextRel]] = true
495			s.nextRel++
496		}
497	}
498	
499	func (s *semSim) allCompleted() bool {
500		for i := 0; i < s.n; i++ {
501			if !s.completed[i] {
502				return false
503			}
504		}
505		return true
506	}
507	
508	func (s *semSim) buildResponse(overflow, stalled bool) semResponse {
509		timeline := make([]semTimelineInterval, 0, len(s.segs))
510		for _, seg := range s.segs {
511			last := len(timeline) - 1
512			if last >= 0 &&
513				timeline[last].TaskID == s.tasks[seg.index].id &&
514				timeline[last].End == seg.start {
515				timeline[last].End = seg.end
516				continue
517			}
518			timeline = append(timeline, semTimelineInterval{
519				TaskID: s.tasks[seg.index].id,
520				Start:  seg.start,
521				End:    seg.end,
522			})
523		}
524	
525		results := make([]semTaskResult, s.n)
526		for i, t := range s.tasks {
527			state := "ready"
528			switch {
529			case s.completed[i]:
530				state = "completed"
531			case s.blockedS[i] != "":
532				state = "blocked"
533			case !s.released[i]:
534				state = "unreleased"
535			}
536			var blockedOn *string
537			if state == "blocked" {
538				m := s.blockedS[i]
539				blockedOn = &m
540			}
541			var deadlineStatus string
542			switch c := s.completion[i]; {
543			case c != nil && *c <= t.deadline:
544				deadlineStatus = "met"
545			case c != nil:
546				deadlineStatus = "missed"
547			case t.deadline <= s.horizon:
548				deadlineStatus = "missed"
549			default:
550				deadlineStatus = "pending"
551			}
552			results[i] = semTaskResult{
553				Executed:       s.executed[i],
554				Completion:     s.completion[i],
555				State:          state,
556				BlockedOn:      blockedOn,
557				DeadlineStatus: deadlineStatus,
558			}
559		}
560	
561		status := "horizon"
562		switch {
563		case overflow:
564			status = "overflow"
565		case s.allCompleted():
566			status = "completed"
567		case stalled:
568			status = "stalled"
569		}
570	
571		resp := semResponse{
572			Status:    status,
573			StoppedAt: s.now,
574			Timeline:  timeline,
575			Results:   results,
576		}
577		if overflow {
578			at := s.now
579			resp.FaultAt = &at
580			id := s.tasks[s.faultTask].id
581			resp.FaultTask = &id
582			sem := s.faultSem
583			resp.FaultSemaphore = &sem
584		}
585		return resp
586	}
